// features/vendor-lifecycle.feature: "A certificate that expires today can still be approved"
// Assumption: the insurance certificate's expiry date is read from the uploaded file's text,
// so the file body states today's date. If the factory fixture offers a dated-document helper,
// prefer it.
import { expect, expectStatus, test, uniqueName, type APIRequestContext } from "../../fixtures";

interface VendorBody {
  id: string;
  status: string;
}

interface DocumentBody {
  id: string;
  status: string;
}

interface ExtractionBody {
  id: string;
  status: string;
}

test.describe("vendor lifecycle", () => {
  test(
    "a certificate that expires today can still be approved",
    { tag: "@LIF-07" },
    async ({ apiAs }) => {
      // Arrange: a member creates a vendor and uploads an insurance certificate expiring today.
      const member: APIRequestContext = await apiAs("member");
      const reviewer: APIRequestContext = await apiAs("reviewer");
      const today = new Date().toISOString().slice(0, 10);

      const created = await expectStatus<VendorBody>(
        await member.post("/api/vendors", {
          data: {
            name: uniqueName("Expiring Today Co"),
            category: "services",
            contact_email: `expiring-${Date.now()}@example.test`,
          },
        }),
        201,
      );

      const uploaded = await expectStatus<DocumentBody>(
        await member.post(`/api/vendors/${created.id}/documents`, {
          multipart: {
            kind: "insurance_certificate",
            file: {
              name: "certificate.txt",
              mimeType: "text/plain",
              buffer: Buffer.from(`Certificate of insurance. Expiration date: ${today}\n`),
            },
          },
        }),
        201,
      );

      // Wait for extraction to finish processing the document.
      await expect
        .poll(
          async () => {
            const doc = await expectStatus<DocumentBody>(
              await member.get(`/api/documents/${uploaded.id}`),
              200,
            );
            return doc.status;
          },
          { timeout: 30_000 },
        )
        .toBe("extracted");

      const extraction = await expectStatus<ExtractionBody>(
        await member.get(`/api/documents/${uploaded.id}/extraction`),
        200,
      );

      // Submit the vendor so it is in review.
      const submitted = await expectStatus<VendorBody>(
        await member.post(`/api/vendors/${created.id}/submit`),
        200,
      );
      expect(submitted.status).toBe("in_review");

      // Act: the reviewer approves the insurance certificate extraction.
      const decision = await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
        data: { decision: "approve" },
      });

      // Assert
      const body = await expectStatus<ExtractionBody>(decision, 200);
      expect(body.status).toBe("approved");
    },
  );
});
